"""Exact cap counterexample/payload and q23 preposition lifetime fixtures."""
from pathlib import Path
import sys

root=Path(sys.argv[1]);path=root/'src/point_add/tests_midg_k24.rs'
test=r'''

#[test]
fn cap24_sc_sw_preposition_boundary_inverse_dirty_phase(){
    let mut b=builder();let _ring=b.alloc_n(276);let q=b.alloc_n(128);let sy=b.alloc_n(8);let sx=b.alloc_n(8);let ph=b.alloc();let pool=b.alloc_n(13);let dirty=b.alloc_n(259);assert_eq!(b.width(),693);
    let owner=pool[8];let mut cycle=q.clone();cycle.push(pool[9]);cycle.extend([pool[11],pool[10],sx[6],sx[7],pool[6],pool[7],ph,sy[7],owner]);assert_eq!(cycle.len(),138);assert_eq!(cycle.last(),Some(&owner));let rec=super::midg::preposition_qk(&mut b,&cycle,&sy,owner,23,pool[12],(1,104),&dirty);let forward=emitted(&mut b,&rec,false);let inverse=emitted(&mut b,&rec,true);let mut rng=Rng::new(0x20261014_2397);
    for block in 0..4{let mut input=vec![0u64;693];for &id in &dirty{input[id.0 as usize]=rng.next();}input[owner.0 as usize]=rng.next();input[pool[12].0 as usize]=u64::MAX;for lane in 0..64{let size=[1usize,41,97,98,99,104][(lane+block)%6];put(&mut input,&sy,lane,N::from(size as u64));put(&mut input,&q[..size],lane,rng.below(size));}let mut expected=input.clone();expected[owner.0 as usize]=0;for lane in 0..64{let size=get(&input,&sy,lane).as_limbs()[0]as usize;let id=q[size+23].0 as usize;expected[id]|=(input[owner.0 as usize]>>lane&1)<<lane;if size<=97{for &id in &q[121..128]{assert_eq!(expected[id.0 as usize]>>lane&1,0);}}}let got=run(&forward,693,&|q|*q=input.clone());assert_eq!(got.q,expected);assert_eq!(got.phase,0);let back=run(&inverse,693,&|q|*q=got.q.clone());assert_eq!(back.q,input);assert_eq!(back.phase,0);let(sym,_)=symbolic(&forward,input.clone());assert_eq!(sym,got.q);let(sym,_)=symbolic(&inverse,got.q);assert_eq!(sym,input);}
    eprintln!("CAP24_SW_OWNER_COMPONENT_PASS cases=256 q23_owner=pool_sw wide_firstcolumn_excluded=true SY_boundaries=97,98,104 maxpark127 small_maxpark120 dirty_passengers=259 inverse=true phase=0 measurement_coefficients=0 scope=preposition_only");
}

#[test]
fn cap24_counterexample8048_exact_column_payload_native(){
    use super::frogdrop_col::{Fd,ColScr,column_pl};let p=super::frogdrop_sched::p();let dx=N::from_str_radix("36f0fbac70592fc4b0dd5063485688e95619d5bfd049d59dddf6c7f7dc28b5a4",16).unwrap();let(mut r,mut t)=(vec![p,dx],vec![N::ZERO,N::from(1u64)]);while !r[r.len()-1].is_zero(){let n=r.len();let q=r[n-2]/r[n-1];r.push(r[n-2]-q*r[n-1]);t.push(t[n-2]+q*t[n-1]);}let j=25;assert_eq!(r[j-1]/r[j],N::from(8505374u64));
    let mut b=builder();let ring=b.alloc_n(276);let q=b.alloc_n(128);let sy=b.alloc_n(8);let sx=b.alloc_n(8);let ph=b.alloc();let pool=b.alloc_n(13);let payload=b.alloc_n(259);assert_eq!(b.width(),693);let rev:Vec<_>=ring.iter().rev().copied().collect();let mut fd=Fd{ring:ring.clone(),q:q.clone(),sy:sy.clone(),sx:sx.clone(),ph,cnt:q[121..].to_vec()};let(cols,_,_)=super::pointadd_frogdrop::col_pars(&super::frogdrop_sched::from_text(super::pointadd_frogdrop::SCHED_FROGDROP));let cp=&cols[24];assert!(cp.hr&&!cp.ht&&!cp.sw&&!cp.dn&&!cp.dl&&!cp.dq&&!cp.psw&&!cp.tt&&cp.sz.1<=255&&cp.sy.1+23<128);let sc=ColScr::carve_col(&pool,&sx,&payload,24,24,40,false);assert!(!sc.sz.contains(&sc.sw));let pl=super::pointadd_frogdrop::pl_col(&payload,&fd,&pool);let record=rec(&mut b,|b|column_pl(b,&mut fd,cp,&sc,Some(&pl)));let forward=emitted(&mut b,&record,false);let inverse=emitted(&mut b,&record,true);let mut max_digit=N::ZERO;
    for seed in 0..4{let mut input=vec![0u64;693];let mut expected=vec![0u64;693];let mut rng=Rng::new(0x20261014_804800+seed);for lane in 0..64{let dy=match lane{0=>N::ZERO,1=>N::from(1u64),2=>p-N::from(1u64),3=>r[j-1]-N::from(1u64),4=>r[j]-N::from(1u64),_=>rng.below(256)%p};let(mut d,mut w)=(dy,N::ZERO);for k in 1..j{let e=d/r[k];d-=e*r[k];let wpost=w.wrapping_add(e.wrapping_mul(t[k]));w=(r[k-1]/r[k]).wrapping_mul(t[k]).wrapping_add(!wpost);}let e=d/r[j];max_digit=max_digit.max(e);let dnext=d-e*r[j];let wpost=w.wrapping_add(e.wrapping_mul(t[j]));let wnext=(r[j-1]/r[j]).wrapping_mul(t[j]).wrapping_add(!wpost);let pre=258-t[j].bit_len();let post=258-t[j+1].bit_len();for l in 0..259{let ib=if l<pre{d.bit(l)}else{w.bit(258-l)};let ob=if l<post{dnext.bit(l)}else{wnext.bit(258-l)};if ib{input[payload[l].0 as usize]|=1u64<<lane;}if ob{expected[payload[l].0 as usize]|=1u64<<lane;}}put(&mut input,&ring,lane,r[j]);put(&mut input,&rev[..t[j].bit_len()],lane,t[j]);put(&mut input,&q,lane,t[j-1]);put(&mut input,&sy,lane,N::from(t[j].bit_len()as u64));put(&mut expected,&ring,lane,r[j+1]);put(&mut expected,&rev[..t[j+1].bit_len()],lane,t[j+1]);put(&mut expected,&q,lane,t[j]);put(&mut expected,&sx,lane,N::from(t[j+1].bit_len()as u64));}
        let got=run(&forward,693,&|words|*words=input.clone());let bad:Vec<_>=got.q.iter().zip(&expected).enumerate().filter_map(|(i,(a,z))|if a!=z{Some(i)}else{None}).collect();assert!(bad.is_empty(),"8048 exact column/payload/scratch seed{seed}; mismatching_wires={bad:?}");assert_eq!(got.phase,0);let back=run(&inverse,693,&|words|*words=got.q.clone());assert_eq!(back.q,input);assert_eq!(back.phase,0);eprintln!("CAP24_PAYLOAD_CASE_PASS seed={seed} lanes=64 exact_oracle=true inverse=true native_phase=0 measurement_coefficients=UNASSESSED");}
    assert!(max_digit>=N::from(1u64)<<23);eprintln!("CAP24_EXACT8048_COMPONENT_PASS width=693 column=24 euclid_step=25 quotient=8505374 max_payload_digit={max_digit} cases=256 q23_owner=sw wide_firstcolumn_excluded=true scope=one_column_with_payload");
}
'''
assert 'fn cap24_sc_sw' not in path.read_text();path.write_text(path.read_text()+test)
